    if (bim_profile->len < 16)
        return;

    char *data = (char *)bim_profile->data;
    char *marker = "8BIM";
    char *pos = data;
    while (pos = strstr(pos, marker)) {
        uint32_t block_size = *(uint32_t*)(pos + 8);
        if (block_size == 0)
            break;

        char *start = pos;
        char *end = start + block_size;
        memmove(start, end, bim_profile->len - (end - data));
        bim_profile->len -= (end - start);
        pos += 4;
    }
}

void remove_resolution_info(StringInfo *bim_profile) {
    if (bim_profile->len < 16)
        return;

    char *data = (char *)bim_profile->data;
    char *end = data + bim_profile->len;

    while (data < end - 3) {
        if (data[0] == '8' && data[1] == 'B' && data[2] == 'I' && data[3] == 'M') {
            char *pixel_info = data + 12;
            int count = *(unsigned short *)(pixel_info + 2);

            if (count > 0) {
                memmove(data, data + count * 2, end - (data + count * 2));
                bim_profile->len -= count * 2;
            }
            break;
        }
        data++;
    }
}

void remove_resolution_info(StringInfo *bim_profile) {
    if (bim_profile->len < 16) {
        return;
    }

    char *data = bim_profile->data;
    for (int i = 0; i <= bim_profile->len - 4; i++) {
        if (data[i] == '8' && data[i + 1] == 'B' && data[i + 2] == 'I' && data[i + 3] == 'M') {
            uint16_t resource_type = *(uint16_t*)(data + i + 4);
            uint16_t resource_length = *(uint16_t*)(data + i + 6);

            if (resource_type == 0x0002 && resource_length >= 10) {
                uint16_t count = *(uint16_t*)(data + i + 8);
                if (count > 0) {
                    memmove(data + i + 8, data + i + 8 + 8, bim_profile->len - i - 8);
                    bim_profile->len -= 8;
                }
            }
            break;
        }
    }
}

